static const uint32_t BLOCK_DIM = 8;
static const uint32_t TILE_K = 256;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    GemmGroupNormHardtanhCustomTilingData tiling;

    const auto* xShape = context->GetInputShape(0);
    const auto* wTShape = context->GetInputShape(1);
    if (xShape == nullptr || wTShape == nullptr) {
        return ge::GRAPH_FAILED;
    }
    // x: [B, K], weight_t: [K, N]
    uint32_t B = static_cast<uint32_t>(xShape->GetOriginShape().GetDim(0));
    uint32_t K = static_cast<uint32_t>(xShape->GetOriginShape().GetDim(1));
    uint32_t K2 = static_cast<uint32_t>(wTShape->GetOriginShape().GetDim(0));
    uint32_t N = static_cast<uint32_t>(wTShape->GetOriginShape().GetDim(1));
    if (K != K2) {
        return ge::GRAPH_FAILED;
    }

    int64_t num_groups_attr = 0;
    (void)context->GetAttr("num_groups", num_groups_attr);
    if (num_groups_attr <= 0 || (N % num_groups_attr) != 0) {
        return ge::GRAPH_FAILED;
    }
    uint32_t G = static_cast<uint32_t>(num_groups_attr);
    uint32_t Gsize = N / G;

    double ht_min = 0.0;
    double ht_max = 0.0;
    (void)context->GetAttr("hardtanh_min", ht_min);
    (void)context->GetAttr("hardtanh_max", ht_max);
    double eps = 1.0e-5;
    (void)context->GetAttr("epsilon", eps);

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_batchSize(B);
    tiling.set_inFeatures(K);
    tiling.set_outFeatures(N);
    tiling.set_numGroups(G);
    tiling.set_groupSize(Gsize);
    tiling.set_tileK(TILE_K);
    tiling.set_hardtanhMin(static_cast<float>(ht_min));
    tiling.set_hardtanhMax(static_cast<float>(ht_max));
    tiling.set_epsilon(static_cast<float>(eps));

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *workspace = context->GetWorkspaceSizes(1);
    workspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

